template:
fn apply_twice<F>(x: i32, f: F) -> i32
where
    F: ⟦bound⟧,
{
    f(x) + f(x)
}

fn main() {
    let count = 10;
    let calc = ⟦closure⟧;
    println!("{}", apply_twice(5, calc));
}

tests:
#[test]
fn applies() {
    let c = 10;
    let calc = |n| n + c;
    assert_eq!(apply_twice(5, calc), 30);
}
